function initThemeToggle(){const n=document.querySelector("#theme-toggle");n&&(n.addEventListener("click",()=>{document.body.classList.toggle("dark-mode"),localStorage.setItem("channapatna-theme",document.body.classList.contains("dark-mode")?"dark":"light")}),"dark"===localStorage.getItem("channapatna-theme")&&document.body.classList.add("dark-mode"))}function renderStats(n,e){const t=document.getElementById(e);t&&(t.innerHTML=n.map(n=>`\n        <div class="stat-card">\n            <span class="stat-icon" aria-hidden="true">${n.icon}</span>\n            <div>\n                <h4>${n.label}</h4>\n                <p>${n.value}</p>\n            </div>\n        </div>\n    `).join(""))}function renderHistory(n,e){const t=document.getElementById(e);t&&(t.innerHTML=n.map(n=>`\n        <div class="history-entry">\n            <div class="history-period">${n.period}</div>\n            <h4>${n.title}</h4>\n            <p>${n.description}</p>\n        </div>\n    `).join(""))}function renderProcess(n,e){const t=document.getElementById(e);t&&(t.innerHTML=n.map(n=>`\n        <div class="process-step">\n            <div class="step-number">${String(n.step).padStart(2,"0")}</div>\n            <div class="step-content">\n                <h4>${n.title}</h4>\n                <p>${n.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderMaterials(n,e){const t=document.getElementById(e);t&&(t.innerHTML=n.map(n=>`\n        <div class="material-card">\n            <div class="material-icon" aria-hidden="true">${n.icon}</div>\n            <h4>${n.name}</h4>\n            <p>${n.description}</p>\n        </div>\n    `).join(""))}function renderDesigns(n,e){const t=document.getElementById(e);t&&(t.innerHTML=n.map(n=>`\n        <div class="design-card">\n            <div class="design-icon" aria-hidden="true">${n.icon}</div>\n            <h4>${n.name}</h4>\n            <p>${n.description}</p>\n        </div>\n    `).join(""))}function renderArtisan(n,e){const t=document.getElementById(e);t&&(t.innerHTML=`\n        <h2>${n.title}</h2>\n        <p>${n.description}</p>\n    `)}function renderGallery(n,e){const t=document.getElementById(e);t&&(t.innerHTML=n.map(n=>`\n        <figure class="gallery-item">\n            <img src="${n.url}" alt="${n.caption}" loading="lazy" onerror="this.closest('.gallery-item').style.display='none';">\n            <figcaption>${n.caption}</figcaption>\n        </figure>\n    `).join(""))}function renderReferences(n,e){const t=document.getElementById(e);t&&(t.innerHTML=n.map(n=>`\n        <li>\n            <a href="${n.link}" target="_blank" rel="noopener noreferrer">${n.text}</a>\n        </li>\n    `).join(""))}document.addEventListener("DOMContentLoaded",()=>{initThemeToggle(),renderStats(CHANNAPATNA_INFO.quickStats,"quick-stats"),renderHistory(HISTORY_CHAPTERS,"history-timeline"),renderProcess(CRAFTING_PROCESS,"process-steps"),renderMaterials(SUSTAINABLE_MATERIALS,"materials-grid"),renderDesigns(TRADITIONAL_DESIGNS,"designs-grid"),renderArtisan(ARTISAN_COMMUNITY,"artisan-community"),renderGallery(GALLERY_IMAGES,"gallery-grid"),renderReferences(REFERENCES,"references")});